{
  "actions": [
    {
      "action": "Track completion separately for every requested item",
      "mechanism": "Aggregate receipt quantities against requested quantities; keep supplier promises separate from physical delivery evidence.",
      "implementation": "Add linked request-line and receipt tables to the existing shared tracker. Show requested, received, remaining, excess, and unresolved-substitution quantities per item.",
      "check": "For ten requested units, receipts of four and three must show seven received, three remaining, and incomplete status.",
      "risk": "Incorrect item mappings can falsely indicate completion."
    },
    {
      "action": "Require a named independent substitution decision",
      "mechanism": "Keep proposed replacements pending until someone other than the requester records an explicit decision and rationale.",
      "implementation": "Assign one existing teammate per substitution. Record requester, original and replacement IDs, quantity conversion, decision, rationale, approver, and timestamp; preserve decision history.",
      "check": "Reject requester self-approval. A delivered but unapproved replacement must remain visible without satisfying the original item.",
      "risk": "An unavailable approver can delay closure; name an eligible backup."
    },
    {
      "action": "Validate receipts before they change completion",
      "mechanism": "Duplicate detection prevents double-counting; excess deliveries create exceptions rather than silently changing requested quantities.",
      "implementation": "Use supplier, receipt number, and line as a uniqueness key; flag matching contents under different numbers. Preserve excess quantities and assign disposition to an existing teammate.",
      "check": "Enter a receipt twice: totals must remain unchanged. Receive twelve against ten: show two excess and unresolved disposition.",
      "risk": "Similar legitimate deliveries need review, not automatic rejection."
    }
  ],
  "abstention_reason": ""
}
